def catalogue(project):
 rom=(project/'local/rolo.md').read_bytes()
 if hashlib.sha256(rom).hexdigest()!=ROM_HASH:raise ValueError('ROM revision mismatch')
 inv=json.loads((project/'docs/stage9/inventory.json').read_text());routines={r['address']:r for r in inv['routines']};accepted={a for r in inv['routines'] for a in r['blocks']};operations=[]
 for entry,(name,contract,gap,role) in sorted(REVIEWS.items()):
  authorized_low={0x417a,0x42e4,0x4b2e,0x9800,0x9826,0x984a,0x989c,0xb114,0xba9e,0xbfe4,0xc142,0xc86c,0xca0a}
  if (entry<0xd000 and entry not in authorized_low) or entry in(0xd11a,0xd1ca):raise ValueError('Outside worker scope')
  addresses=sorted(set(routines[entry]['blocks']));items=[];ranges=[];fields=[];absolute=[]
  for address in addresses:
   if address not in accepted:raise ValueError('Unaccepted boundary')
   item=Decoder(rom,address).decode();items.append(item)
   if ranges and ranges[-1]['end_exclusive']==address:ranges[-1]['end_exclusive']=address+item['size']
   else:ranges.append(dict(start=address,end_exclusive=address+item['size']))
   for match in re.finditer(r'\(\+([0-9]+),(A[0-6])(?:,[^)]*)?\)',item['operands']):
    destination=match.end()==len(item['operands']) and item['mnemonic'].split('.')[0] not in('TST','BTST','CMP','CMPI','LEA','JSR','JMP')
    fields.append(dict(site=address,offset=int(match[1]),register=match[2],instruction=item['mnemonic'],role='destination/write-or-RMW' if destination else 'source/read-or-address',operand=match[0]))
   for match in re.finditer(r'\(\$([0-9A-F]+)\)\.(L|W)',item['operands']):
    destination=match.end()==len(item['operands']) and item['mnemonic'].split('.')[0] not in('TST','BTST','CMP','CMPI','LEA','JSR','JMP')
    absolute.append(dict(site=address,address=int(match[1],16),instruction=item['mnemonic'],role='destination/write-or-RMW' if destination else 'source/read-or-address'))
  for r in ranges:r.update(bytes=rom[r['start']:r['end_exclusive']].hex(),sha256=hashlib.sha256(rom[r['start']:r['end_exclusive']]).hexdigest())
  defs=[dict(address=d['address'],bytes=rom[d['address']:d['address']+34].hex()) for d in inv['object_definitions'] if d['handler']==entry]
  operations.append(dict(entry=f'{entry:04X}',address=entry,name=name,status='reviewed_partial',role=role,contract=contract,pending=gap+' Candidategraphoverincludesotherlevels; noactualLevel1execution, fullABI/alias/nativefidelity orwholelevelclaim.',instruction_evidence=items,code_ranges=ranges,field_access_evidence=fields,absolute_access_evidence=absolute,call_sites=[i for i in items if i['mnemonic'] in('BSR','JSR')],branch_sites=[i for i in items if i['flow'] in('branch','jump')],immutable_definitions=defs,evidence_scope='Accepted reachableblocks for inventoryentry; rangesmayincludejoinedfragments/branches. Semanticreviewisscopedcontract,notautomaticcompletionfromdisassembly.'))
